import type { FeaturedDossier } from "./featuredDossiers";

type Impact = "BULL CASE" | "BEAR CASE" | "NEUTRAL";
type Spec = {
  ticker: string;
  cik: string;
  description: string;
  lede: string;
  sells: string;
  revenueModel: string;
  opportunity: string;
  mustGoRight: string;
  editorNote: string;
  bull: string[];
  bear: string[];
  thesisBreaker: string;
  drivers: [string, string, string][];
  risks: [string, "High" | "Medium", string, string][];
  monitor: [string, string, Impact][];
  questions: string[];
  competitors: string;
  peers: [string, string][];
  investorUrl: string;
  newsroomUrl: string;
};

const secBrowse = (cikOrTicker: string) => `https://www.sec.gov/edgar/browse/?CIK=${encodeURIComponent(cikOrTicker)}&owner=exclude`;
const secForm = (cik: string, form: string) => `https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=${cik}&type=${encodeURIComponent(form)}&owner=exclude&count=40`;

function makeDossier(spec: Spec): FeaturedDossier {
  return {
    ticker: spec.ticker,
    reviewed: "August 1, 2026",
    completeness: 100,
    newsroomUrl: spec.newsroomUrl,
    description: spec.description,
    lede: spec.lede,
    sells: spec.sells,
    revenueModel: spec.revenueModel,
    opportunity: spec.opportunity,
    mustGoRight: spec.mustGoRight,
    editorNote: spec.editorNote,
    bullTitle: "What can compound owner value",
    bull: spec.bull,
    bearTitle: "What can impair the thesis",
    bear: spec.bear,
    thesisBreaker: spec.thesisBreaker,
    financialDrivers: [
      ...spec.drivers.map(([label, value, detail]) => ({ label, value, detail })),
      { label: "BALANCE SHEET", value: "Capacity and resilience", detail: "Track liquidity, debt, pension or lease obligations, commitments, and the cost of funding through the cycle." },
      { label: "PER-SHARE VALUE", value: "Cash conversion", detail: "Reconcile reported earnings with operating cash flow, capital spending, acquisitions, dividends, repurchases, and diluted share count." },
    ],
    risks: [
      ...spec.risks.map(([title, level, text, signal]) => ({ title, level, text, signal })),
      { title: "Capital allocation", level: "Medium", text: "Acquisitions, repurchases, dividends, debt reduction, and internal investment can create or destroy per-share value.", signal: "Return on invested capital, leverage, share count, impairment charges, and post-deal performance" },
      { title: "Legal, regulatory, and reporting risk", level: "Medium", text: "Regulation, litigation, tax, cybersecurity, and accounting judgments can alter cash flows or constrain strategy.", signal: "New proceedings, remedies, restatements, control weaknesses, and material changes in risk-factor language" },
    ],
    monitor: [
      ...spec.monitor.map(([title, text, impact]) => ({ title, text, impact })),
      { title: "Quarterly thesis audit", text: "Compare new filings with prior promises, isolate changed assumptions, and record evidence that strengthens or weakens the owner thesis.", impact: "NEUTRAL" },
    ],
    questions: [
      ...spec.questions,
      "Which management commitment is most important to verify in the next two reporting periods?",
      "What measurable development would invalidate the current owner thesis rather than merely create short-term volatility?",
    ],
    competitors: spec.competitors,
    comparables: spec.peers.map(([name, ticker]) => ({
      name,
      ticker,
      ownership: "Public",
      relationship: `Operating and valuation reference for ${spec.ticker}`,
      valuation: "Use current enterprise value, earnings, cash flow, and sector-appropriate multiples; normalize accounting and capital intensity.",
      financialStatus: `Compare growth, margins, balance-sheet capacity, cash conversion, and competitive position with ${spec.ticker}.`,
      sourceUrl: secBrowse(ticker),
    })),
    sources: [
      { title: `${spec.ticker} SEC filing library`, meta: "SEC EDGAR · Primary source", href: secBrowse(spec.cik), excerpt: `The SEC filing record provides ${spec.ticker}'s annual, quarterly, current, proxy, ownership, and registration disclosures.` },
      { title: `${spec.ticker} annual reports`, meta: "SEC Forms 10-K · Primary filings", href: secForm(spec.cik, "10-K"), excerpt: "Annual filings describe the business, segments, competition, audited financial statements, commitments, controls, and material risks." },
      { title: `${spec.ticker} quarterly reports`, meta: "SEC Forms 10-Q · Primary filings", href: secForm(spec.cik, "10-Q"), excerpt: "Quarterly filings update results, cash flow, balance-sheet items, contingencies, and management discussion between annual reports." },
      { title: `${spec.ticker} proxy statements`, meta: "SEC DEF 14A · Governance source", href: secForm(spec.cik, "DEF 14A"), excerpt: "Proxy filings disclose board oversight, executive incentives, ownership, related matters, and shareholder proposals." },
      { title: `${spec.ticker} investor relations`, meta: "Company primary materials", href: spec.investorUrl, excerpt: "Official earnings releases, presentations, events, governance materials, and shareholder information published by the company." },
      { title: `${spec.ticker} official newsroom`, meta: "Company announcements", href: spec.newsroomUrl, excerpt: "Official product, operational, leadership, partnership, and corporate announcements used as management assertions pending independent verification." },
    ],
  };
}

